        jit = candidate._qsa_prefill_score_kernel.fn.fn

        class WithMode:
            def __getitem__(self, grid):
                def launch(*a, **kw):
                    # Existing boundary helpers request stage2; exercise stage1.
                    kw["num_stages"] = 1
                    return jit[grid](*a, **kw, QUERY_PARTS=parts)

