    modes = (1, 2) if dtype == torch.float8_e4m3fn else (1,)
    for stages, parts in itertools.product((2, 1), modes):
        candidate = trial.candidate_module(common.production)
        entry = candidate._qsa_prefill_score_kernel
        configs = [
